import Redis from 'ioredis';

const redis = new Redis({
  host: 'localhost',
  port: 6379,
  password: process.env.REDIS_PASSWORD,
  lazyConnect: true,
  retryStrategy: (times) => {
    const delay = Math.min(times * 50, 2000);
    return delay;
  },
});

await redis.connect();

const CACHE_KEY = 'product:101';
const TTL_SECONDS = 300;

// Set with TTL
await redis.set(CACHE_KEY, JSON.stringify({ id: 101, name: 'Widget', price: 29.99 }), 'EX', TTL_SECONDS);

// Get
const raw = await redis.get(CACHE_KEY);
const product = raw ? JSON.parse(raw) : null;

// Delete
await redis.del(CACHE_KEY);

const pipeline = redis.pipeline();

pipeline.set('user:1:name', 'Alice', 'EX', 300);
pipeline.set('user:1:email', 'alice@example.com', 'EX', 300);
pipeline.set('user:1:role', 'admin', 'EX', 300);

const results = await pipeline.exec();

async function getCachedProduct(id: number) {
  try {
    const raw = await redis.get(`product:${id}`);
    if (raw) return JSON.parse(raw);

    // Cache miss — fetch from source
    const product = await fetchProductFromDB(id);
    await redis.set(
      `product:${id}`,
      JSON.stringify(product),
      'EX',
      300
    );
    return product;
  } catch (err) {
    console.error('Redis error:', err);
    // Fallback to source without caching
    return fetchProductFromDB(id);
  }
}
